import { NextResponse } from "next/server";
import { createClient } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin-server";
import { isSameOriginMutation } from "@/lib/security/request-origin";
import { rateLimit } from "@/lib/security/rate-limit";

/** Connection time is generated by the server; clients cannot update another account. */
export async function POST(request: Request) {
  if (!isSameOriginMutation(request))
    return NextResponse.json({ error: "Origine invalide" }, { status: 403 });
  const db = await createClient();
  const {
    data: { user },
  } = await db.auth.getUser();
  if (!user)
    return NextResponse.json({ error: "Non connecté" }, { status: 401 });
  if (!rateLimit(`connection:${user.id}`, 4, 60000).allowed)
    return NextResponse.json({ error: "Trop de requêtes" }, { status: 429 });
  const admin = createAdminClient();
  if (!admin)
    return NextResponse.json({ error: "Suivi indisponible" }, { status: 503 });
  const { data: current, error: readError } =
    await admin.auth.admin.getUserById(user.id);
  if (readError || !current.user)
    return NextResponse.json({ error: "Compte indisponible" }, { status: 503 });
  const stamp = new Date().toISOString();
  const { error } = await admin.auth.admin.updateUserById(user.id, {
    app_metadata: {
      ...current.user.app_metadata,
      mybasket_last_connected_at: stamp,
    },
  });
  return error
    ? NextResponse.json(
        { error: "Actualisation indisponible" },
        { status: 503 },
      )
    : NextResponse.json({ connectedAt: stamp });
}
